You can find the second largest element in $O(n)$ time without sorting by tracking the top two values:

```python
def second_largest(numbers: list[int]) -> int | None:
    unique_nums = set(numbers)
    if len(unique_nums) < 2:
        return None
    first = second = float('-inf')
    for n in unique_nums:
        if n > first:
            second, first = first, n
        elif n > second:
            second = n
    return int(second)

print(second_largest([12, 35, 1, 10, 34, 1]))  # Output: 34
