    def __init__(self, environment, alpha=0.1, gamma=0.9):
        self.env = environment 
        self.q_table = np.zeros(self.env.state_space + (self.env.action_space,))
        self.alpha = alpha 
        self.gamma = gamma

    def get_best_action(self, state):
        return np.argmax(self.q_table[state])

