Generators can be chained like Unix pipes (`cat | grep | cut`) to build memory-efficient streaming ETL pipelines:

```python
# Simulated log stream
log_lines = [
    "INFO 200 /api/users",
    "ERROR 500 /api/checkout",
    "INFO 200 /api/products",
    "ERROR 404 /api/missing",
    "INFO 200 /api/orders"
]

# Stage 1: Filter errors
def filter_errors(lines):
    for line in lines:
        if "ERROR" in line:
            yield line

# Stage 2: Extract endpoints
def extract_endpoints(error_lines):
    for line in error_lines:
        parts = line.split()
        yield parts[2]

# Stage 3: Formatting
def format_alerts(endpoints):
    for ep in endpoints:
        yield f"ALERT: Failure at {ep}"

# Execute pipeline lazily
pipeline = format_alerts(extract_endpoints(filter_errors(log_lines)))
for alert in pipeline:
