class Car:
    def __init__(self, color, make, model, year):
        self.color = color
        self.make = make
        self.model = model
        self.year = year
        self.fuel_level = 0
        self.mileage = 0
        self.current_speed = 0
        self.is_running = False

    def start(self):
        if self.fuel_level < 0.1:
            print("Cannot start the car. Low fuel level.")
        else:
            self.is_running = True
            print("The car has started")

    def stop(self):
        self.is_running = False
        self.mileage += self.current_speed
        print("The car has stopped")

    def accelerate(self, speed):
        if not self.is_running:
            print("Cannot accelerate. The car is not running.")
            return

        if self.fuel_level < 0.1:
            print("Cannot accelerate. Low fuel level.")
            return

        if speed > 200:
            print("Cannot accelerate beyond the maximum speed limit of 200 km/h.")
            self.current_speed = 200
        else:
            self.current_speed = speed
        print(f"The car is accelerating to {self.current_speed} km/h")

    def brake(self, speed):
        if not self.is_running:
            print("Cannot brake. The car is not running.")
            return

        if speed < 0:
            print("Cannot brake beyond 0 km/h.")
            self.current_speed = 0
        else:
            self.current_speed = speed
        print(f"The car is braking to {self.current_speed} km/h")

    def refuel(self, amount):
        print(f"Refueling the car with {amount} liters of fuel.")
        self.fuel_level += amount
        if self.fuel_level > 50:
            self.fuel_level = 50

    def drive(self, distance):
        if not self.is_running:
            print("Cannot drive. The car is not running.")
            return

        fuel_consumption = distance * 5
        if self.fuel_level < fuel_consumption:
